// ═══════════════════════════════════════════════════════════════════════
// Top Fuel — NHRA Dragstrip (1000 ft / ~305m straight)
// ═══════════════════════════════════════════════════════════════════════
const dragStripLength = 600;
const dragLanes = 2;
const dragReference: Point2D[] = [];
const dragInner: Point2D[] = [];
const dragOuter: Point2D[] = [];

for (let i = 0; i <= 100; i++) {
  const x = 100 + (i / 100) * dragStripLength;
  dragReference.push({ x, y: 300 });
  dragInner.push({ x, y: 260 });
  dragOuter.push({ x, y: 340 });
}

const dragTrack: TrackGeometry = {
  name: 'NHRA Championship Dragstrip',
  country: 'USA',
  lengthKm: 0.305,
  totalLaps: 1,
  type: 'drag',
  referenceLine: dragReference,
  innerEdge: dragInner,
  outerEdge: dragOuter,
  startFinishIdx: 0,
  rotation: 0,
};

// ═══════════════════════════════════════════════════════════════════════
// HELPER: create circuit TrackGeometry concisely
// ═══════════════════════════════════════════════════════════════════════
function makeCircuit(
  name: string, country: string, lengthKm: number, totalLaps: number,
  ctrl: Point2D[], width = 12, pps = 45,
): TrackGeometry {
  const ref = catmullRomLoop(ctrl, pps);
  return {
    name, country, lengthKm, totalLaps, type: 'circuit',
    referenceLine: ref,
    innerEdge: offsetPolyline(ref, -width),
    outerEdge: offsetPolyline(ref, width),
    startFinishIdx: Math.floor(ref.length * 0.95),
    drsZones: [
      { startIdx: Math.floor(ref.length * 0.88), endIdx: Math.floor(ref.length * 0.98) },
      { startIdx: Math.floor(ref.length * 0.25), endIdx: Math.floor(ref.length * 0.35) },
    ],
    sectors: [
      { name: 'S1', startIdx: 0, endIdx: Math.floor(ref.length * 0.33) },
      { name: 'S2', startIdx: Math.floor(ref.length * 0.33), endIdx: Math.floor(ref.length * 0.66) },
      { name: 'S3', startIdx: Math.floor(ref.length * 0.66), endIdx: ref.length - 1 },
    ],
    rotation: 0,
  };
}

